<?php require_once 'includes/config.php'; requireUser(); $uid=(int)$_SESSION['user_id']; $conn->query("UPDATE complaints SET is_escalated=1 WHERE status='Pending' AND is_escalated=0 AND date_submitted<=DATE_SUB(NOW(),INTERVAL 3 DAY)"); $s=$conn->prepare('SELECT * FROM complaints WHERE user_id=? ORDER BY date_submitted DESC');$s->bind_param('i',$uid);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$total=count($rows);$pending=count(array_filter($rows,fn($r)=>$r['status']==='Pending'));$progress=count(array_filter($rows,fn($r)=>$r['status']==='In Progress'));$resolved=count(array_filter($rows,fn($r)=>$r['status']==='Resolved'));$title='My Complaints'; require 'includes/header.php'; ?><div class="hero"><div><h1>Welcome, <?=e($_SESSION['user_name'])?> 👋</h1><p class="subtitle">Report an issue and follow its progress.</p></div><a class="btn btn-primary" href="report_incident.php">+ Report complaint</a></div><div class="stats"><div class="stat-card"><div class="label">Total</div><div class="value"><?=$total?></div></div><div class="stat-card pending"><div class="label">Pending</div><div class="value"><?=$pending?></div></div><div class="stat-card"><div class="label">In progress</div><div class="value"><?=$progress?></div></div><div class="stat-card resolved"><div class="label">Resolved</div><div class="value"><?=$resolved?></div></div></div><div class="toolbar"><input data-filter="tbody tr" placeholder="Search my complaints..."><select data-status-filter="tbody tr"><option value="">All statuses</option><option>Pending</option><option>In Progress</option><option>Resolved</option></select></div><div class="table-card"><div class="table-wrap"><table><thead><tr><th>ID</th><th>Complaint</th><th>Category</th><th>Date</th><th>Status</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5" class="empty">You have not submitted any complaints yet.</td></tr><?php endif; foreach($rows as $r):?><tr data-status="<?=e($r['status'])?>"><td>#<?=$r['id']?></td><td><?=e($r['description'])?><?php if($r['is_escalated']):?><div><span class="badge badge-escalated"><span class="pulse"></span>Escalated</span></div><?php endif;?></td><td><span class="category-tag"><?=e($r['category'])?></span></td><td><?=date('d M Y, g:i A',strtotime($r['date_submitted']))?><?php if($r['status']!=='Resolved'): ?><br><small><?=max(0,(int)floor((time()-strtotime($r['date_submitted']))/86400))?> day(s) old</small><?php endif; ?></td><td><span class="badge <?= $r['status']==='Resolved'?'badge-resolved':($r['status']==='In Progress'?'badge-progress':'badge-pending')?>"><?=e($r['status'])?></span></td></tr><?php endforeach;?></tbody></table></div></div><?php require 'includes/footer.php'; ?>
